-- Espelho local (SQLite) de supabase/migrations/20261112121709_intelligence_voice_capture.sql, usado pelos testes locais.
-- SQLite nao altera CHECK: as duas tabelas sao recriadas com as regras novas e os dados copiados.
CREATE TABLE `capture_consents_new` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL, `email` text NOT NULL, `mode` text NOT NULL CHECK (`mode` IN ('lesson','interview','voice')), `policy_version` text NOT NULL, `camera` integer NOT NULL DEFAULT 0, `photos` integer NOT NULL DEFAULT 0, `recording` integer NOT NULL DEFAULT 0, `accepted_at` integer NOT NULL, `revoked_at` integer, `voice` integer NOT NULL DEFAULT 0, CHECK ((`mode`='voice' AND `voice`=1 AND `camera`=0 AND `photos`=0 AND `recording`=0) OR (`mode`<>'voice' AND `voice`=0)));
INSERT INTO `capture_consents_new` (`id`,`user_id`,`email`,`mode`,`policy_version`,`camera`,`photos`,`recording`,`accepted_at`,`revoked_at`) SELECT `id`,`user_id`,`email`,`mode`,`policy_version`,`camera`,`photos`,`recording`,`accepted_at`,`revoked_at` FROM `capture_consents`;
CREATE TABLE `capture_items_new` (`id` text PRIMARY KEY NOT NULL, `consent_id` text NOT NULL, `session_id` text NOT NULL, `kind` text NOT NULL CHECK (`kind` IN ('photo','recording','voice')), `moment` text NOT NULL CHECK (`moment` IN ('answer_start','expression','interval','session','script_line','room_tone')), `key` text NOT NULL UNIQUE, `mime` text NOT NULL, `size` integer NOT NULL CHECK (`size` > 0), `created_at` integer NOT NULL, `script_version` text, `line_id` text, `duration_ms` integer, `sample_rate` integer, FOREIGN KEY (`consent_id`) REFERENCES `capture_consents`(`id`), CHECK ((`kind`='voice' AND `mime`='audio/wav' AND `script_version` IS NOT NULL AND `duration_ms` BETWEEN 300 AND 40000 AND `sample_rate` BETWEEN 16000 AND 96000 AND ((`moment`='script_line' AND `line_id` IS NOT NULL) OR (`moment`='room_tone' AND `line_id` IS NULL))) OR (`kind`<>'voice' AND `moment` NOT IN ('script_line','room_tone') AND `script_version` IS NULL AND `line_id` IS NULL AND `duration_ms` IS NULL AND `sample_rate` IS NULL)));
INSERT INTO `capture_items_new` (`id`,`consent_id`,`session_id`,`kind`,`moment`,`key`,`mime`,`size`,`created_at`) SELECT `id`,`consent_id`,`session_id`,`kind`,`moment`,`key`,`mime`,`size`,`created_at` FROM `capture_items`;
DROP TABLE `capture_items`;
DROP TABLE `capture_consents`;
ALTER TABLE `capture_consents_new` RENAME TO `capture_consents`;
ALTER TABLE `capture_items_new` RENAME TO `capture_items`;
CREATE INDEX `capture_consents_user` ON `capture_consents` (`user_id`,`accepted_at`);
CREATE INDEX `capture_items_session` ON `capture_items` (`session_id`,`created_at`);
CREATE INDEX `capture_items_voice_line_idx` ON `capture_items` (`consent_id`,`script_version`,`line_id`,`created_at`) WHERE `kind`='voice';
